  croquis: {titre: "Structure et composition de la population togolaise", svg: "<svg viewBox=\"0 0 500 270\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n  <rect width=\"500\" height=\"270\" fill=\"#F8F6F0\" rx=\"8\"/>\n  <text x=\"250\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\" fill=\"#1F5C52\">STRUCTURE ET COMPOSITION DE LA POPULATION TOGOLAISE</text>\n  <!-- Composition ethnique -->\n  <rect x=\"15\" y=\"34\" width=\"200\" height=\"200\" rx=\"6\" fill=\"#E8F4F8\" stroke=\"#2563EB\"/>\n  <text x=\"115\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#2563EB\" font-weight=\"bold\">GROUPES ETHNIQUES</text>\n  <text x=\"35\" y=\"70\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Groupe Adja-Éwé (Sud) :</text>\n  <text x=\"35\" y=\"84\" font-size=\"8\" fill=\"#555\">Éwé, Adja, Ouatchi, Mina</text>\n  <text x=\"35\" y=\"102\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Groupe Kabyè-Tem (Centre-N) :</text>\n  <text x=\"35\" y=\"116\" font-size=\"8\" fill=\"#555\">Kabyè, Tem (Kotokoli), Lamba</text>\n  <text x=\"35\" y=\"134\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Groupe Para-Gourma (Nord) :</text>\n  <text x=\"35\" y=\"148\" font-size=\"8\" fill=\"#555\">Moba, Gourma, Bassar</text>\n  <text x=\"35\" y=\"166\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Étrangers :</text>\n  <text x=\"35\" y=\"180\" font-size=\"8\" fill=\"#555\">Ghanéens, Béninois...</text>\n  <text x=\"115\" y=\"210\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">+40 ethnies au total</text>\n  <text x=\"115\" y=\"224\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">4 langues véhiculaires</text>\n  <!-- Structure -->\n  <rect x=\"225\" y=\"34\" width=\"260\" height=\"200\" rx=\"6\" fill=\"#FFF3E0\" stroke=\"#C68A2E\"/>\n  <text x=\"355\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#C68A2E\" font-weight=\"bold\">STRUCTURE DÉMOGRAPHIQUE</text>\n  <text x=\"245\" y=\"70\" font-size=\"9\" fill=\"#555\">Population : 8,7 millions (RGPH-5, 2022)</text>\n  <text x=\"245\" y=\"86\" font-size=\"9\" fill=\"#555\">Croissance : ~2,3% par an</text>\n  <text x=\"245\" y=\"102\" font-size=\"9\" fill=\"#555\">Densité : ~153 hab/km²</text>\n  <text x=\"245\" y=\"118\" font-size=\"9\" fill=\"#555\">Jeune : 60% ont moins de 25 ans</text>\n  <text x=\"245\" y=\"134\" font-size=\"9\" fill=\"#555\">Féminine : légèrement > hommes</text>\n  <text x=\"355\" y=\"158\" text-anchor=\"middle\" font-size=\"10\" fill=\"#C68A2E\" font-weight=\"bold\">RÉPARTITION</text>\n  <text x=\"245\" y=\"175\" font-size=\"9\" fill=\"#555\">• Maritime (Lomé) : la + dense</text>\n  <text x=\"245\" y=\"189\" font-size=\"9\" fill=\"#555\">• Plateaux : 2e région</text>\n  <text x=\"245\" y=\"203\" font-size=\"9\" fill=\"#555\">• Savanes : sous-peuplée</text>\n  <text x=\"245\" y=\"217\" font-size=\"9\" fill=\"#555\">• Urb. : 42% · Rural : 58%</text>\n</svg>", img: null, legende: "Schéma de la structure démographique du Togo."},
