    {titre: "L'industrialisation au Togo", svg: "<svg viewBox=\"0 0 500 270\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n  <rect width=\"500\" height=\"270\" fill=\"#F8F6F0\" rx=\"8\"/>\n  <text x=\"250\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\" fill=\"#1F5C52\">L'INDUSTRIALISATION AU TOGO</text>\n  <rect x=\"15\" y=\"34\" width=\"225\" height=\"200\" rx=\"6\" fill=\"#E8F4F8\" stroke=\"#2563EB\"/>\n  <text x=\"127\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#2563EB\" font-weight=\"bold\">INDUSTRIES EXISTANTES</text>\n  <text x=\"35\" y=\"70\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Industries agroalimentaires :</text>\n  <text x=\"35\" y=\"84\" font-size=\"8\" fill=\"#555\">Brasseries, huileries, moulins</text>\n  <text x=\"35\" y=\"98\" font-size=\"8\" fill=\"#555\">Égrenage du coton (NSCT)</text>\n  <text x=\"35\" y=\"116\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Industries minières :</text>\n  <text x=\"35\" y=\"130\" font-size=\"8\" fill=\"#555\">Phosphate (Kpémé, 1er afr.)</text>\n  <text x=\"35\" y=\"144\" font-size=\"8\" fill=\"#555\">Clinker (ciment)</text>\n  <text x=\"35\" y=\"158\" font-size=\"8\" fill=\"#555\">Calcaire (Tabligbo)</text>\n  <text x=\"35\" y=\"176\" font-size=\"9\" fill=\"#1F5C52\" font-weight=\"bold\">Autres industries :</text>\n  <text x=\"35\" y=\"190\" font-size=\"8\" fill=\"#555\">Textiles, savonneries</text>\n  <text x=\"35\" y=\"204\" font-size=\"8\" fill=\"#555\">Zone franche (Lomé)</text>\n  <text x=\"35\" y=\"218\" font-size=\"8\" fill=\"#555\">Port de Lomé</text>\n  <rect x=\"255\" y=\"34\" width=\"230\" height=\"200\" rx=\"6\" fill=\"#FFEBEE\" stroke=\"#A6472B\"/>\n  <text x=\"370\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#A6472B\" font-weight=\"bold\">PROBLÈMES ET SOLUTIONS</text>\n  <text x=\"270\" y=\"70\" font-size=\"9\" fill=\"#A6472B\" font-weight=\"bold\">Limites actuelles :</text>\n  <text x=\"270\" y=\"84\" font-size=\"8\" fill=\"#555\">• Peu d'industries transform.</text>\n  <text x=\"270\" y=\"98\" font-size=\"8\" fill=\"#555\">• Énergie insuffisante</text>\n  <text x=\"270\" y=\"112\" font-size=\"8\" fill=\"#555\">• Manque de capitaux</text>\n  <text x=\"270\" y=\"126\" font-size=\"8\" fill=\"#555\">• Technologie limitée</text>\n  <text x=\"370\" y=\"148\" text-anchor=\"middle\" font-size=\"9\" fill=\"#047857\" font-weight=\"bold\">Solutions :</text>\n  <text x=\"270\" y=\"164\" font-size=\"8\" fill=\"#555\">• Zone franche (Lomé)</text>\n  <text x=\"270\" y=\"178\" font-size=\"8\" fill=\"#555\">• Barrage Nangbéto</text>\n  <text x=\"270\" y=\"192\" font-size=\"8\" fill=\"#555\">• Partenariats publics-privés</text>\n  <text x=\"270\" y=\"206\" font-size=\"8\" fill=\"#555\">• Formation professionnelle</text>\n  <text x=\"270\" y=\"220\" font-size=\"8\" fill=\"#555\">• Industrialisation PND</text>\n</svg>", img: null, legende: "Schéma des principales industries du Togo et leur localisation."},
    {titre: "Ressources minières et énergétiques du Togo (document authentique)", svg: null, img: "photos_hg/g3_8_ressources_minieres.jpeg", legende: "Carte des ressources minières exploitées (phosphate, calcaire, fer, marbre) et non exploitées (or, uranium, chromite), avec le barrage de Nangbéto."}
