  croquis: {titre: "Le Togo, une nation en devenir", svg: "<svg viewBox=\"0 0 500 270\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n  <rect width=\"500\" height=\"270\" fill=\"#F8F6F0\" rx=\"8\"/>\n  <text x=\"250\" y=\"22\" text-anchor=\"middle\" font-weight=\"bold\" font-size=\"13\" fill=\"#1F5C52\">LE TOGO, UNE NATION EN DEVENIR</text>\n  <text x=\"250\" y=\"38\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">Indépendance : 27 avril 1960 · République 5e : 2024 · Superficie : 56 785 km²</text>\n  <!-- Atouts -->\n  <rect x=\"15\" y=\"50\" width=\"220\" height=\"175\" rx=\"6\" fill=\"#E8F5E9\" stroke=\"#047857\"/>\n  <text x=\"125\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#047857\" font-weight=\"bold\">ATOUTS</text>\n  <text x=\"35\" y=\"86\" font-size=\"9\" fill=\"#555\">• Position géographique stratégique</text>\n  <text x=\"35\" y=\"100\" font-size=\"9\" fill=\"#555\">  (hub logistique, Port de Lomé)</text>\n  <text x=\"35\" y=\"114\" font-size=\"9\" fill=\"#555\">• Diversité culturelle (40+ ethnies)</text>\n  <text x=\"35\" y=\"128\" font-size=\"9\" fill=\"#555\">• Ressources nat. (phosphate, calcaire)</text>\n  <text x=\"35\" y=\"142\" font-size=\"9\" fill=\"#555\">• Population jeune et dynamique</text>\n  <text x=\"35\" y=\"156\" font-size=\"9\" fill=\"#555\">• Stabilité politique récente</text>\n  <text x=\"35\" y=\"170\" font-size=\"9\" fill=\"#555\">• PND 2018-2022 / Togo 2025</text>\n  <text x=\"35\" y=\"184\" font-size=\"9\" fill=\"#555\">• Secteur financier (Ecobank)</text>\n  <text x=\"35\" y=\"198\" font-size=\"9\" fill=\"#555\">• Accès mer (pour pays enclavés)</text>\n  <!-- Défis -->\n  <rect x=\"260\" y=\"50\" width=\"225\" height=\"175\" rx=\"6\" fill=\"#FFEBEE\" stroke=\"#A6472B\"/>\n  <text x=\"372\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A6472B\" font-weight=\"bold\">DÉFIS</text>\n  <text x=\"280\" y=\"86\" font-size=\"9\" fill=\"#555\">• Pauvreté (IDH moyen)</text>\n  <text x=\"280\" y=\"100\" font-size=\"9\" fill=\"#555\">• Chômage des jeunes</text>\n  <text x=\"280\" y=\"114\" font-size=\"9\" fill=\"#555\">• Accès eau potable et élect.</text>\n  <text x=\"280\" y=\"128\" font-size=\"9\" fill=\"#555\">• Industrie peu développée</text>\n  <text x=\"280\" y=\"142\" font-size=\"9\" fill=\"#555\">• Dépendance aide extérieure</text>\n  <text x=\"280\" y=\"156\" font-size=\"9\" fill=\"#555\">• Déforestation, changem. climat.</text>\n  <text x=\"280\" y=\"170\" font-size=\"9\" fill=\"#555\">• Insécurité Nord (terrorisme)</text>\n  <text x=\"280\" y=\"184\" font-size=\"9\" fill=\"#555\">• Émigration des jeunes</text>\n  <!-- Vision -->\n  <rect x=\"15\" y=\"236\" width=\"470\" height=\"26\" rx=\"6\" fill=\"#1F5C52\" opacity=\".15\" stroke=\"#1F5C52\"/>\n  <text x=\"250\" y=\"250\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1F5C52\" font-weight=\"bold\">Vision Togo 2063 : pays émergent, paix, démocratie, développement durable</text>\n  <text x=\"250\" y=\"262\" text-anchor=\"middle\" font-size=\"8\" fill=\"#555\">« Unité · Paix · Solidarité » — devise nationale du Togo</text>\n</svg>", img: null, legende: "Schéma des défis et atouts du Togo indépendant sur la voie du développement."},
